```tsx
import { useId } from "react";
import type { ReactElement } from "react";
import "./CodeCard.css";

export interface CodeCardProps {
  /** Heading shown above the snippet. */
  title: string;
  /** The SQL snippet to display and copy. */
  code: string;
  /** Called with the snippet when the Copy button is activated. */
  onCopy: (code: string) => void;
}

export function CodeCard({ title, code, onCopy }: CodeCardProps): ReactElement {
  const titleId = useId();

  return (
    <section className="code-card" aria-labelledby={titleId}>
      <header className="code-card__header">
        <h2 id={titleId} className="code-card__title">
          {title}
        </h2>
        <button
          type="button"
          className="code-card__copy"
          aria-label={`Copy ${title}`}
          onClick={() => onCopy(code)}
        >
          Copy
        </button>
      </header>
      <pre className="code-card__code" tabIndex={0} aria-labelledby={titleId}>
        <code>{code}</code>
      </pre>
    </section>
  );
}
```

