.code-card {
  display: grid;
  gap: 0.75rem;
  padding: clamp(0.9rem, 2vw, 1.25rem);
  border: 1px solid var(--hair);
  border-radius: 12px;
  background: var(--slide);
  color: var(--ink);
  font: inherit;
}

.code-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.code-card__title {
  margin: 0;
  font: inherit;
  font-size: clamp(0.95rem, 1.6vw, 1.1rem);
  font-weight: 600;
  color: var(--ink);
}

.code-card__copy {
  flex: none;
  padding: 0.35rem 0.9rem;
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.8rem, 1.4vw, 0.9rem);
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease;
}

.code-card__copy:hover {
  background: var(--myelin);
  border-color: var(--myelin);
  color: var(--slide);
}

.code-card__code {
  margin: 0;
  padding: clamp(0.75rem, 1.6vw, 1rem);
  overflow-x: auto;
  border-radius: 8px;
  background: var(--code-bg);
  color: var(--ink);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  font-size: clamp(0.8rem, 1.5vw, 0.9rem);
  line-height: 1.5;
  white-space: pre;
}

.code-card__code code {
  font: inherit;
  color: inherit;
}

:root[data-motion="reduce"] .code-card__copy {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .code-card__copy {
    transition: none;
  }
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
